// Pull webhook body + token from their respective nodes.
const webhookBody = $('Webhook: Lark Base record created').first().json.body ?? $('Webhook: Lark Base record created').first().json;
const token = $json.tenant_access_token;

// Lark Base automation sends {record: {...}} or event subscription sends {event: {record: {...}}}.
const rec = webhookBody.record ?? webhookBody.event?.record ?? webhookBody;
const fields = rec.fields ?? webhookBody.fields ?? {};

return [{
  json: {
    tenant_access_token: token,
    record_id: rec.record_id ?? rec.id ?? webhookBody.record_id,
    fields
  }
}];

const key = $('Load answer key').first().json;
const n   = $('Normalize webhook + carry token').first().json;
const fields = $('Lark: fetch full record').first().json.data?.record?.fields || {};

return key.questions.map(q => ({
  json: {
    record_id: n.record_id,
    tenant_access_token: n.tenant_access_token,
    name:  fields[key.fields.name]  ?? '',
    email: fields[key.fields.email] ?? '',
    passing_percent: key.passing_percent,
    rubric_version:  key.version,
    question: q,
    answer:  (fields[q.field_name] ?? '').toString(),
  }
}));

const { question, answer } = $json;
const norm = s => question.normalize === 'trim_lower'
  ? String(s ?? '').trim().toLowerCase()
  : String(s ?? '').trim();

const match = norm(answer) === norm(question.expected ?? '');
return [{
  json: {
    ...$json,
    per_question: {
      id: question.id,
      type: 'exact',
      score_field: question.score_field,
      score: match ? question.weight : 0,
      max:   question.weight,
      feedback: match ? 'Correct.' : 'Incorrect.'
    }
  }
}];

const item = $input.first().json;
const question = item.question;
const answer   = item.answer;

let raw = item.message?.content ?? item.choices?.[0]?.message?.content ?? item.text ?? '';
let out;
try { out = typeof raw === 'string' ? JSON.parse(raw) : raw; }
catch { out = { score: 0, reasoning: 'Malformed LLM output, defaulted to 0.', missing_points: [], keywords_found: [] }; }

const maxQ = question.max_score ?? 5;
let score = Math.max(0, Math.min(maxQ, Number(out.score) || 0));

if (question.required_keywords?.length) {
  const lower = (answer || '').toLowerCase();
  const missing = question.required_keywords.filter(k => !lower.includes(k.toLowerCase()));
  if (missing.length) score = Math.min(score, Math.floor(maxQ / 2));
}

const weighted = (score * question.weight) / maxQ;
return [{
  json: {
    ...item,
    per_question: {
      id: question.id,
      type: 'scenario',
      score_field: question.score_field,
      score: weighted,
      max:   question.weight,
      raw_score: score,
      max_raw:   maxQ,
      feedback:  out.reasoning ?? '',
      missing:   out.missing_points ?? []
    }
  }
}];

const items = $input.all().map(i => i.json.per_question);
const n     = $('Normalize webhook + carry token').first().json;
const key   = $('Load answer key').first().json;
const fields = $('Lark: fetch full record').first().json.data?.record?.fields || {};

const score = items.reduce((s, q) => s + q.score, 0);
const max   = items.reduce((s, q) => s + q.max,   0);
const percent = max > 0 ? Math.round((score / max) * 1000) / 10 : 0;
const pass = percent >= key.passing_percent;

// Build the Lark Base fields PATCH body: per-question score fields + TOTAL + RESULTS.
const patchFields = {};
for (const q of items) {
  if (q.score_field) patchFields[q.score_field] = q.score;
}
patchFields[key.fields.total]  = score;
patchFields[key.fields.result] = pass ? 'PASS' : 'FAIL';

return [{
  json: {
    record_id: n.record_id,
    tenant_access_token: n.tenant_access_token,
    name:  fields[key.fields.name]  ?? '',
    email: fields[key.fields.email] ?? '',
    per_question: items,
    score, max, percent,
    result: pass ? 'PASS' : 'FAIL',
    passing_percent: key.passing_percent,
    rubric_version: key.version,
    patch_fields: patchFields,
    graded_at: new Date().toISOString()
  }
}];

